INSERT INTO changelog (title, body, created_at) VALUES ('Джері памʼятає кожного клієнта і не починає з нуля; точніший голос', 'Памʼять по клієнту: у картці клієнта (Огляд) зверху блок «Що Джері памʼятає про клієнта»: де ми зараз, домовленості (гроші, обсяг, терміни), що вже зроблено, що далі. Після кожної розмови про клієнта Джері сам її оновлює, навіть у загальному чаті чи Telegram, якщо назвеш клієнта. Можна правити руками. Кнопка «Джері, зібрати / оновити» збирає памʼять з історії, задач і переписки.
Коли просиш план чи наступні кроки, Джері тепер бачить памʼять, історію робіт, закриті задачі і останні повідомлення групи. План будує від поточного етапу, а не з нуля, і не ставить задач на те, що вже зроблено. Назвав клієнта в загальному чаті («план для Аквавіти») — Джері сам підтягує його стан.
Голос: остаточний текст тепер розпізнається з усього запису (точніше, ніж живий потоковий), а «причісування» лише ставить розділові знаки і правильні назви, слова не міняє. Якщо змінило більше ~15% слів — лишається твій сирий текст.', datetime('now'));
